import{_ as a,o as t,c as i,a3 as r}from"./chunks/framework.CcKC9xfe.js";const u=JSON.parse('{"title":"Yarilo Documentation","description":"Yarilo is a cloud-native mail server in Go for Kubernetes: IMAP, POP3, LMTP, Submission, JMAP and Sieve. Install, configure, deploy, migrate and operate it.","frontmatter":{"description":"Yarilo is a cloud-native mail server in Go for Kubernetes: IMAP, POP3, LMTP, Submission, JMAP and Sieve. Install, configure, deploy, migrate and operate it.","head":[["link",{"rel":"canonical","href":"https://doc.yarilomail.org/latest/"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/latest/"}],["meta",{"property":"og:title","content":"Yarilo Documentation"}],["meta",{"name":"twitter:title","content":"Yarilo Documentation"}],["meta",{"property":"og:description","content":"Yarilo is a cloud-native mail server in Go for Kubernetes: IMAP, POP3, LMTP, Submission, JMAP and Sieve. Install, configure, deploy, migrate and operate it."}],["meta",{"name":"twitter:description","content":"Yarilo is a cloud-native mail server in Go for Kubernetes: IMAP, POP3, LMTP, Submission, JMAP and Sieve. Install, configure, deploy, migrate and operate it."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/latest/#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/latest/\\",\\"headline\\":\\"Yarilo Documentation\\",\\"description\\":\\"Yarilo is a cloud-native mail server in Go for Kubernetes: IMAP, POP3, LMTP, Submission, JMAP and Sieve. Install, configure, deploy, migrate and operate it.\\",\\"dateModified\\":\\"2026-10-31T12:43:41.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"WebSite\\",\\"@id\\":\\"https://doc.yarilomail.org/#website\\",\\"url\\":\\"https://doc.yarilomail.org/\\",\\"name\\":\\"Yarilo documentation\\",\\"inLanguage\\":\\"en\\",\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"Organization\\",\\"@id\\":\\"https://yarilomail.org/#organization\\",\\"name\\":\\"YariloMail\\",\\"alternateName\\":\\"Yarilo\\",\\"url\\":\\"https://yarilomail.org/\\"}]}"]]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1793450621000}'),o={name:"index.md"};function n(l,e,s,h,d,m){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="yarilo-documentation" tabindex="-1">Yarilo Documentation <a class="header-anchor" href="#yarilo-documentation" aria-label="Permalink to &quot;Yarilo Documentation&quot;">​</a></h1><p>Yarilo is a mail server written in Go and built for Kubernetes. It serves IMAP, POP3, LMTP, Submission, JMAP and ManageSieve, filters mail with Sieve, and stores it in maildir, sdbox or mdbox.</p><p>One set of binaries covers every shape, from a single node to a director ring in front of several backends. Moving between shapes is a change to the configuration, not to the software.</p><h2 id="getting-a-server-running" tabindex="-1">Getting a server running <a class="header-anchor" href="#getting-a-server-running" aria-label="Permalink to &quot;Getting a server running&quot;">​</a></h2><ul><li><a href="/latest/installation/">Installation</a> - the first working instance, with Docker Compose or the Helm chart.</li><li><a href="/latest/installation/dns.html">DNS for a mail domain</a> - MX, SPF, DKIM, DMARC and PTR records.</li><li><a href="/latest/installation/general.html">General configuration</a> - how <code>yarilo.<wbr>yaml</code> is laid out, TLS and hostnames.</li></ul><h2 id="configuring-mail" tabindex="-1">Configuring mail <a class="header-anchor" href="#configuring-mail" aria-label="Permalink to &quot;Configuring mail&quot;">​</a></h2><ul><li>Protocols: <a href="/latest/protocols/imap.html">IMAP</a>, <a href="/latest/protocols/pop3.html">POP3</a>, <a href="/latest/protocols/lmtp.html">LMTP</a>, <a href="/latest/protocols/submission.html">Submission</a> and <a href="/latest/protocols/jmap.html">JMAP</a>.</li><li><a href="/latest/auth/">Authentication</a> - password databases, <a href="/latest/auth/scram.html">SCRAM</a>, <a href="/latest/auth/oauth2.html">OAuth 2.0</a> and <a href="/latest/auth/master_users.html">master users</a>.</li><li><a href="/latest/storage/">Mailbox storage</a> - formats, <a href="/latest/storage/namespace.html">namespaces</a> and <a href="/latest/storage/quota.html">quota</a>.</li><li><a href="/latest/features/sieve.html">Sieve</a> and <a href="/latest/features/fts.html">full-text search</a>.</li></ul><h2 id="running-it-in-production" tabindex="-1">Running it in production <a class="header-anchor" href="#running-it-in-production" aria-label="Permalink to &quot;Running it in production&quot;">​</a></h2><ul><li><a href="/latest/installation/deployment.html">Deployment</a> - the Helm chart, sizing, and the standalone and director layouts.</li><li><a href="/latest/architecture/">Architecture</a> - the services and how a user is routed to a backend.</li><li><a href="/latest/operations/yarilo_admin.html">yarctl</a> for day-to-day administration, and <a href="/latest/operations/smoke.html">smoke tests</a> after each rollout.</li></ul><h2 id="moving-from-another-server" tabindex="-1">Moving from another server <a class="header-anchor" href="#moving-from-another-server" aria-label="Permalink to &quot;Moving from another server&quot;">​</a></h2><ul><li><a href="/latest/installation/migration.html">Migration</a> - converting existing mailboxes and keeping message identifiers stable.</li><li><a href="/latest/architecture/parity.html">Feature coverage</a> - what is implemented, feature by feature, and what is not.</li></ul><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><ul><li><a href="/latest/reference/settings.html">All settings</a> - every <code>yarilo.<wbr>yaml</code> key with its type, default and chart value.</li><li><a href="/latest/reference/rfcs.html">RFC support</a> - the standards each service implements, and how far.</li></ul><p>Source code and issues live on <a href="https://github.com/yarilomail" target="_blank" rel="noreferrer">GitHub</a>.</p>',14)])])}const f=a(o,[["render",n]]);export{u as __pageData,f as default};
